(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,100124,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function s(e){let s={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:t,AnketaPoint:d,AnketaProse:h,Whisper:j}=s;return r||n("AnketaCollapse",!0),c||n("AnketaGroup",!0),t||n("AnketaList",!0),d||n("AnketaPoint",!0),h||n("AnketaProse",!0),j||n("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(t,{children:[(0,i.jsx)(d,{title:"Имя персонажа [русс|англ]",children:(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Оливер Пфайффер | Oliver Pfeiffer"})})}),(0,i.jsx)(d,{title:"Возраст",children:(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"прожитый на земле: 42 года."}),"\n",(0,i.jsx)(s.li,{children:"дата рождения — 20.02.1595г. | смерти — 01.09.1637г."}),"\n",(0,i.jsx)(s.li,{children:"прожитый в Загробном мире как грешная душа: 381 год"}),"\n"]})}),(0,i.jsx)(d,{title:"Пол",children:(0,i.jsx)(s.p,{children:"Мужской"})}),(0,i.jsxs)(d,{title:"Раса",children:[(0,i.jsx)(s.p,{children:"Ракшаса."}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"Человек, что провёл всю сознательную жизнь на войне и потерял там человечность — это изначально прекрасный кандидат на становление одним из ракшас. Но этого мало: Оливер — человек, что не гнушается собственных поступков и которому во снах никогда не приходили убитые. Он коварный и прожорливый, импульсивный и гневливый, жестокий, беспощадный и прагматичный — эталонный ракшас из палаты мер и весов."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(h,{children:[(0,i.jsx)(s.p,{children:"В ту пасмурную осень Средневековья, когда последователи Лютера обезжиривали церковь, а Папа Римский раздумывал об организации глобальной Божьей кары — рождалось бескомпромиссное зло в миниатюре. Становление Оливера Пфайффера происходило в рамках типичной Европы тех лет. Ведь европейская Европа — это эстетика вещей довольно мрачных и некрасивых. Вокруг постоянные убийства. Чума и голод. Тотальное мародёрство. Мораль отсутствует как явление, и всё выглядит до ужаса апокалиптично. При таких обстоятельствах хочешь не хочешь, а с головой что-то произойдёт, внутри что-то щёлкнет, и всё станет восприниматься как-то по-другому. Очень цинично, с позиций практичности и шкурного интереса, без морализаторства или просто сочувствия. Кого-то убили? Ну что ж, бывает. Сам виноват! Зачем на улицу без меча вышел? А? Что? Кого-то ограбили? Ну ничего! Такое здесь постоянно! А? Пришли грабить и убивать меня? А вот тут уж простите, у меня есть меч — и нападающие вырезаются под корень."}),(0,i.jsx)(s.p,{children:"Словом, вокруг происходит фирменный бардак: кровь, кишки, гроб, кладбище. И чаще выживает сильный, чем слабый. Настолько, что слабые со временем физически заканчиваются. На это можно резонно заявить: «Ну, это всё лирика. Очередные оправдания какого-нибудь болезненного ублюдка и бесславного насильника, а что по фактам? Кем он был? Что им руководило и какой у него был характер?» О!.. Это был человек специфичный. Что-то между «кровожадный военный преступник» и «исполнительный герой тяжёлой войны», чаще склоняясь в пользу первого. Оливер Пфайффер хотя и происходит из дворянской семьи, но мало кто может назвать его благородным в полной мере: он дворянин по крови, не по восприятию. В нём исчезающе мало заносчивости, в нём нет мрачного христианского бу-бу-бу."}),(0,i.jsx)(s.p,{children:"Он образован и в определённой мере начитан. Но начитанность и образованность сглаживаются постоянным нахождением в кругу людей более простых и приземлённых. Он на одинаковом уровне орудует как и довольно сложными речевыми конструкциями, так и языком откровенных отбросов и нефильтрованного быдла. Оливер является обладателем увесистого характера — характера, который норовит кого-нибудь приплюснуть и раздавить. Он агрессивен и холеричен. Постоянные приступы неконтролируемого гнева, бешенство и необузданность — его спутники по жизни. Увы, но тут ничего не попишешь: как человеку пробивному, ему жизненно необходима пробивная способность. А у Пфайффера она рождается из гнева."}),(0,i.jsx)(s.p,{children:"К тому же он — лоснящийся обжора, страшный едок и самый преданный фанат сытных блюд и пышных обедов. Оливер никогда не упускал возможности нажраться до отвала, пока пузо не увеличится втрое, а рожа от удовольствия не раздвинется в стороны. Такая преданность вкусной еде часто выходила ему боком. Особенно когда не было адекватной возможности заниматься снабжением, а армии приходилось голодать. И хотя он часто объедал своих товарищей, терпеть военные лишения ему всё-таки приходилось не единожды. Во многом именно по этой причине он быстро пристрастился к еде скорее вкусной, чем обильной. До ужаса циничный и беспринципный, Оливер изобретателен в военном ремесле. Он жил, живёт и будет жить войной, а война постоянно подразумевает хитрость, решительность и напор. Это опасная и по-настоящему страшная работа, но в первую очередь работа. Именно по этой причине он достаточно исполнителен, неприхотлив и трудолюбив, чтобы в моменты напряжения не давать заднюю, не действовать вполоборота и не принимать полумеры. Расчётливый, прагматичный и последовательный, он всегда пытается довести дело до конца."}),(0,i.jsx)(s.p,{children:"Пфайффер — лидер, который способен вдохновлять людей и влечь за собой. Он жесток, амбициозен и деспотичен. Он не стесняется кровавости собственных методов, он мыслит в парадигме «вижу цель — не вижу препятствий», забрало падает и он прыгает в бесконечность. А в качестве издержек всегда будут чужие жизни, пока он не добьётся своего и не устаканится на заполученном."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(t,{children:[(0,i.jsx)(d,{title:"Потеря рассудка",children:(0,i.jsx)(s.p,{children:"Боится бесповоротно потерять рассудок. Со времён Магдебурга и по сей день Оливера преследуют параноидальные мысли, что у него в какой-то момент окончательно сорвёт крышу. Это вполне закономерно: он — убийца и насильник, а ещё, кстати, каннибал. И он этого даже не стесняется! Но ведь всему есть предел — та линия, которую ни в коем случае нельзя переходить. А Оливер подошёл к ней слишком близко."})}),(0,i.jsx)(d,{title:"Огонь",children:(0,i.jsx)(s.p,{children:"После событий в Магдебурге Оливер стал опасаться и откровенно побаиваться огня. Не огня камина или костра, но бушующее, неконтролируемое пламя, всякий настоящий пожар или того хуже — вот это реально его пугает."})}),(0,i.jsx)(d,{title:"Сталкер",children:(0,i.jsx)(s.p,{children:"Учитывая род его деятельности, Оливер боится встретить Сталкера. Он считает, что перед таким могущественным существом, как Сталкер, даже он абсолютно бессилен — и это не может не настораживать."})}),(0,i.jsx)(d,{title:"Слепота",children:(0,i.jsx)(s.p,{children:"Боится ослепнуть."})})]})}),(0,i.jsx)(r,{title:"Мечты и цели",children:(0,i.jsxs)(h,{children:[(0,i.jsx)(s.p,{children:"Добиться собственного превосходства, доминирования в загробном мире. Обрести власть и установить единый порядок в Энкраже. Или помочь кому-то власти добиться, а через него повлиять на общее положение вещей."}),(0,i.jsx)(s.p,{children:"Получить более высокое положение в обществе ракшас."}),(0,i.jsx)(s.p,{children:"Изучить пустых и вступить с ними в контакт."}),(0,i.jsx)(s.p,{children:"Заполучить по-настоящему могущественный артефакт в свои руки."}),(0,i.jsx)(s.p,{children:"Любыми методами поменять расстановку сил в Энкраже и изменить существующий порядок в совершенно иную сторону."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(h,{children:[(0,i.jsx)(s.p,{children:"Эффективный менеджер, что виртуозно обращается с людским ресурсом и решает всякие-разные задачки по мере их поступления, а также умелый и старательный исполнитель, мыслящий в категориях «необходимость не знает закона» — это, собственно, кто? Это Оливер Пфайффер — человек, вылупившийся на свет на территории Германии и оперившийся во времена деятельности небезызвестного Альбрехта фон Валленштайна. Жил и куролесил он в местах, где волки срать боялись, во времена, когда людей вешали чисто из соображений удобства и практичности. Проще говоря, чисто ради прикола."}),(0,i.jsx)(s.p,{children:"Итак, декорации. Священная Римская империя, 17 век. Католики и протестанты нещадно пускают друг друга под нож, не сильно на этот счёт рефлексируя и потихоньку-помаленьку пробираясь сквозь уйму противоречий древности. Кашу заварили ещё их отцы и деды, а расхлёбывают сыны, внуки и правнуки. Император усиленно пытается со всем этим бардаком разобраться и навести в своей феодальной коммуналке порядок. В этом ему помогает огромная армия наёмников под предводительством уже упомянутого Альбрехта фон Валленштайна, практически ключевой фигуры тогдашних кровавых, но, безусловно, крайне занимательных событий. Совсем недавно в общий замес влезла с ногами и руками Дания, но только-только засучив рука, была оперативно помножена на ноль войсками императора. И вот где-то здесь и выползает на свет наш главный герой, в прошлом сын мелкого дворянина, а с недавних пор ни много ни мало офицер имперской армии. До этого момента он представлял из себя никого и ничто, по сути пустоту, которая смогла заполниться только со временем и в виду описываемых событий. Занимал рядовые должности и ничем по-крупному не отмечался. И смог взлететь по карьерной лестнице ввысь именно в тот момент, когда Альбрехт фон Валленштайн со своей армией наёмников расквартировался в Магдебурге, Хальберштадте, Бранденбурге и отдельных районах Богемии. Но давайте немного вернёмся в прошлое и узнаем, кто такой Оливер Пфайффер и что его привело в такую интересную компанию. Мужчина был выходцем из довольно скромной дворянской семьи и уроженцем Аугсбурга, что в Баварии, а потому его судьба сразу стала немножко предрешённой. Почему? Всё вполне просто и непримечательно: спустя пару десятилетий после его рождения в Европе начнётся самая кровавая за всю историю наблюдений межрелигиозная мясорубка. Будут массово слетать головы с плеч, людей будут заживо сжигать в сараях, кровью умоются вообще все, никто не уйдёт обиженным или обделённым. И ведь самый смех ситуации в том, что Оливера воспитывали в католических традициях, до определённого момента он души не чаял в святости и непогрешимости Папы Римского, а также очень скоро возненавидел ближних своих — протестантов. По сути эти вещи предопределили его судьбу. Сначала никому неизвестный баварский мальчик получил минимально необходимое для небогатого дворянина образование, более-менее успешно отучившись в католическом училище, а после почти расшибся о гранит науки католического университета. Ему, честно говоря, и в училище не шибко нравилось, гораздо чаще он предпочитал увеселяющий мордобой и воодушевляющее баварское пиво, а в университете настала скука смертная. Благо, что терпеть уныние мирного времени ему оставалось совсем недолго. Ещё в детстве Пфайффер выявил в себе тягу к разного рода физическим упражнениям, когда отдубасил до полусмерти нескольких крепких ребят из Богемии. Он так помял им бока, так повыбивал половину зубов, что у них ещё долго челюсть была набекрень, а под глазами тускнели фиолетовые фингалы. Носы у богемских ребятишек были основательно вогнаны вглубь черепа, а из кривых ноздрей долгими неделями вытекала кровь вперемешку с соплями. Их перекорёженные лунообразные рожи можно было бы спокойно и вполне успешно демонстрировать в кунсткамере эрцгерцога Фердинанда 2 в Тироле или в кунсткамере императора Рудольфа 2 в Праге. Львиную долю своей юности и даже дальше Оливер с гордостью вспоминал тот прекрасный летний денёк, когда эти двое подставляли свои ослиные морды под его увесистый кулак. — Я так им ёбла разлопатил, так мощно надавал пиздюлей, что эти несуразные уёбы вовек, блять, не забудут таких душевных прочуханов! — с нескрываемой радостью рассказывал он друзьям. А потом в Чехии разразилось восстание. Пфайффер не упустил возможности проявить качества своего молодого тестостерона, а поэтому оперативно поступил на службу в имперскую армию и отправился подавлять чешских бунтовщиков. В дальнейшем былая религиозность, которая прививалась ему с детства, скорректировалась временем, проведённым на службе. Он всё ещё верил в Бога, но ставил под сомнение целесообразность и нужность огромного количества различных ритуалов и прочих благоглупостей, направленных на увещевание высшего существа на небе. С тех пор ему всегда казалось странным то положение вещей, когда в Библии написано одно, а окружающие его пастыри рассказывают о диаметрально противоположном. Большинство религиозников он стал воспринимать как откровенных болванов и удивительных любителей несусветных помоев. Под «религиозниками» он имел в виду чересчур набожных персонажей, удивительных кадров, что были готовы ради просветления и икон посадить на кол собственного ребёнка и не испытывать по этому поводу никаких трудностей. Таких персонажей в Германии было с избытком, из-за чего Оливеру приходилось долгое время мириться с определёнными бытовыми неурядицами. А тем временем тучи реально сгущались. Внутри императорского дворца думали о глобальном переделе, на севере князья всё больше наглели, строили козни и занимались мутными схематозами. Каждый второй размышлял о том, как бы получше кого-нибудь обезжирить и не получить взамен по роже. Все натягивали сову своих неуёмных амбиций на глобус реального положения вещей. И раскручивался маховик исторического процесса, предельно безразличного к людским жизням. Война продолжалась. Итак, до этого мы остановились на том, что главнокомандующий Валленштайн с огромным войском устроил стоянку и Оливера повысили в звании. Но почему конкретно его повысили? А всё дело было в его удивительной исполнительности и в его по-настоящему мёртвой хватке. Тогда на территории Германии одновременно разбушевалась чума и случился неурожай, жить и просто существовать на некоторых территориях не представлялось возможным в принципе, а армии срочно нужно было что-то жрать и где-то жить. Оливера Пфайффера назначили квартирмейстером, и он вместе с остальными шакалами логистики принялся за работу. Алгоритм был прост: он отсылал на место солдат, в какую-нибудь захудалую деревушку с десятком хижин, и там крестьянам предлагали два стула: либо здешнее мужичьё оперативно мобилизуется и вступает в имперскую армию, попутно в добровольном порядке отдавая часть своего имущество, либо их флегматично пускают на фарш и имущество в любом случае конфискуется. Но конфискуется уже в добровольно-принудительном порядке. В то время как даже самым лучшим охотникам на крестьянскую жилплощадь и крестьянское имущество, обиравшим Германию, удавалось собрать максимум 200% выгоды со своей деятельности, то Оливер собирал все 300%. Он выполнял свою работу исключительно кроваво и максимально продуктивно."}),(0,i.jsx)(s.p,{children:"Так, имел место случай, когда подручная солдатня Пфайффера завалилась в церковь, в штатном режиме намереваясь выкрасть всё тамошнее имущество, демонтировать свинцовый церковный шпиль и переплавить его на металл для пушек. Но отличающийся смелостью священник решил воспрепятствовать подобным злодеяниям, не имея при себе никакого иного оружия, кроме веры в Господа Бога, и ему отрубили ноги и руки и оставили умирать на алтаре, в окружении множества икон и запачканных его же кровью колонн. Другая ситуация, произошедшая в Кольберге, не менее решительно свидетельствовала о предельной жестокости Оливера и его приспешников, а также об особой форме озабоченности, когда дело касалось наживы. Основательно помяв местных жителей, солдатня сожгла друг за другом пять церквей, десятки амбаров и складов, а затем принялась предавать огню дома измученных горожан. Когда же горожанам удалось спасти большую часть своего имущества в главном храме, солдаты пришли туда и разом всё отобрали. Четверть города была безвозвратно экстерминирована, а уцелевшая часть обезжирена. В дальнейшем солдаты Валленштайна стали занимать всё больше новых территорий, а соответственно возрастала и нужда армии во всё новых и новых средствах для существования. Закономерным образом росло и количество славных подвигов Пфайффера, совершённых во благо снабжения имперской армии всем необходимым. В Тироле перемалывали на хлеб бобовые стебли, в Нассау перемалывали на хлеб жёлуди и корни. Чудом выжившие крестьяне скорее напоминали зомби, чем живых людей, и обессиленно копали грядки. А вокруг был Оливер Пфайффер. Получивший новые полномочия и людей, он с удовольствием обрушивал на крестьян чудовищные поборы, а бюргеров, не способных адекватно приютить и снабдить имперскую армию, поил «шведским коктейлем»: смесью человеческих и животных экскрементов с кипятком. Со временем массовые поборы, смерть, война и голод стали чем-то на уровне специфических погодных явлений. Уже никто не удивлялся ни тому, что кто-то умер, ни тому, что кого-то ограбили. Это было в порядке вещей. И каждый раз, когда подворачивалась соответствующая возможность, один другого убивал и грабил. Все стали считать это вполне закономерным и даже нормальным. Многие вещи изменились, когда Валленштайна, до недавнего времени командующего армией императора, отстранили от командования по многочисленным подозрениям. Вероятно, что такому исходу поспособствовали дворцовые интриги в Вене, но в связи с этим событием католиков в дальнейшем будет сопровождать огромное количество неприятностей."}),(0,i.jsx)(s.p,{children:"К тому моменту из-за острой нехватки умелых офицеров Пфайфферу приходилось делить обязанности пополам: когда не было активных боевых действий, он отвечал за снабжение, а во время битв внезапно начинал выполнять и боевые функции. Тем не менее не будет лишним промотать небольшое количество малоинтересных событий и в качестве альтернативы привести отрывок из письма Оливера, которое он написал своему брату, находившемуся тогда в Баварии: «Дорогой брат, на этот счёт я скажу тебе следующее: мы постоянно убиваем, и день ото дня грабёж сменяется пожаром, а пожар — грабежом, и этому нет и не будет конца. Валленштайн с недавнего времени отстранён от командования; я почти уверен, что в нём засела либо обида, либо в нём появился злокозненный умысел, поскольку мы уже не первый месяц не можем получить из Фридланда, Загана и большей части Мекленбурга никаких продуктов. Это всё личные владения Валленштайна, и в недавние годы именно из них мы получали множество провианта и с помощью него же вели войну против множества противников. Сейчас мы не можем получить оттуда в достатке даже зерно. Не хватает лошадей, а поэтому пушки приходиться тянуть людям. Большинство пушек неисправны и требуют немедленного ремонта. Отсутствуют офицеры, мало пороха, нет в достаточном количестве кирок и лопат, нет денег на пристойное жалование, поэтому люди уходят в свободное плавание. Армия утрачивает свою боеспособность на глазах и медленно разлагается. Исчезающе мало еды... И со всем этим Тилли, наш новый военачальник, по велению его величества Императора Фердинанда сместивший с этой должности Валленштайна, совместно со своим заместителем Паппенгеймом решается приблизиться к Магдебургу. Большинство наших войск так или иначе расквартировано в Мекленбурге и по всей долине Одера. Таким образом, мы двигаемся сверху вниз. Утверждается, что король Швеции прямо сейчас находится неподалёку самого Магдебурга. Вижу необходимым уточнить, что раньше этот город был нашим формальным союзником, но совсем недавно перешёл на сторону противника. Учитывая имеющиеся у меня сведения, я предположу, что Тилли и Паппенгейм в намерениях захватить и использовать Магдебург как кормовую базу и плацдарм для последующих наступлений. Ещё есть сообщения, будто король Швеции до этого двинулся на Франкфурт-на-Одере и попытался его у нас выбить. Насколько мне известно, таковая попытка не увенчалось успехом, и вскоре мы встретимся с ним лицом к лицу. Честно говоря, дорогой брат, я не знаю, чем всё это кончится, но события последних дней не предвещают нам ничего хорошего...»"}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"МАГДЕБУРГ"})}),(0,i.jsx)(s.p,{children:"Голодные солдаты, у каждого второго из которых болела головя от решительного недостатка углеводов, выстроились длинными шеренгами на немногочисленных холмиках перед Магдебургом. «Традиции нужно соблюдать, — считало командование, — а поэтому перед штурмом войску необходимо религиозное напутствие». Оливер отреагировал неоднозначно, поскольку считал, что перед штурмом справлять религиозную нужду вовсе необязательно, а иногда и полностью контрпродуктивно. Ветеранам изнасилований, мастерам избиений и просто братству отпетых негодяев, у половины из которых совесть давным-давно демонтировали, предлагают перед боем пронаблюдать за священными ритуалами. Само такое решение продиктовано квадратно-гнездовым армейским дебилизмом, когда решения принимаются не индивидуально, а скорее коллективным армейским разумом, никогда не отличавшимся интеллектуализмом и начитанностью. — Господи помилуй, какую удивительную хуйню они только не выдумают, — про себя бурчал Пфайффер. В течение следующего времени армия наёмников, своим видом напоминавшая скорее орду заядлых вурдалаков и поистине страшных упырей, наблюдала за церковным богослужением. Великое множество капелланов и просто священников, словно южноамериканские индейцы, резво прыгали по полю и друг за другом выкрикивали на латыни: «Dominus vobiscum!» и «Et cum spiritu tuo!». Католические мистические благовония, исходящие из ладанов, совсем скоро смешались с доминирующим сатанинским запахом дерьма из ближайших солдатских сортиров, а поэтому процессия приобретала всё новые коричневые ноты. Но, не смотря на преждевременный скептицизм Оливера, такая служба оказала на войско самое благоприятное впечатление, и к середине он заулыбался сам. Перед городом стали виднеться первые приготовления: пушки, заранее отремонтированные и заранее приведённые в полную боевую готовность, встали на изготовку и смотрели в сторону Магдебурга. Потом стало видно, как католические наёмники бегают взад-вперёд, офицеры проводят дополнительные муштрования, а артиллеристы ехидно давят лыбу и романтично поглядывают на городские стены. Досточтимые магдебургские бюргеры напряглись. Возможно, некоторым из них всё ещё казалось, будто на город внезапно спустится спасительное благословение, и они смогут отогнать орду наёмников только при помощи божественного провидения. Но если такие мысли и появлялись в разгорячённых головах горожан, то они забывали одну простую вещь: что они, протестанты, что наёмники, католики, верят в одного Бога. Но судьба города была предрешена ещё тогда, когда досточтимые бюргеры Магдебурга решили принять за стратегию одну чудесную концепцию: вертеть жопой на все стороны, преследовать только свои шкурные интересы, а после толком не отвечать за базар. За это и поплатились. Чисто из католического великодушия осаждённым в последний раз предложили сдаться и тихо-мирно всё урегулировать. С позором капитулировать перед нависшей угрозой город отказался. Заговорили пушки. На протяжении трёх полных суток город нещадно раздалбливают пушечными ядрами и забрасывают наёмническим мясом, на что со стен слышится голосистое тевтонское «wir haben eure Mütter gefickt». «Про маму было лишнее...», — думают наёмники, а на четвёртый день поджигают магдебургские ворота и проламывают их. И после того, как через ворота Магдебурга понеслись католики, несчастных руководителей города и его бедолажных обывателей ждало только одно: католики их всех сейчас страшно перережут. Оголодавшие оборванцы и жуткие бармалеи с длинными бородами, наёмники очень быстро обезумели и вышли из-под офицерского контроля. Католическое воинство состояло не из самых приличных и скромных людей, их воспитание оставляло желать лучшего, а предшествующая штурму голодуха и сам штурм сказались на психическом состоянии солдатни ещё пуще. Большинство наёмников было набрано из откровенных сёл, абсолютных захолустий и мест, где не появлялся ни один городской человек. Они не ели многие и многие месяцы, были до ужасной степени истощены, а горожане, что сейчас сверкают пятками только при одном их виде, ещё недавно обливали наёмников помоями и стреляли по ним из амбразур. Сейчас эти люди оказались в действительно примечательной ситуации, когда никто им не указ, а мир за пределами ближайшей лесополосы выглядит по-настоящему лакшери. Что же можно предпринять в такой ситуации? Правильный ответ: бесперебойно бухать, радостно насиловать всё живое и шевелящееся женского пола, оптимистично убивать всё живое и шевелящееся пола мужского, а также плевать на осточертевших офицеров. Оливер, как один из примерных офицеров, подумал в следующем ключе: не можешь остановить — возглавь. По-страшному облизнувшись, он стал выглядеть как сбежавший из психдиспансера. На лице появилась детская радость, глаза заблестели, а рот очень неприятно раззявился. — С Богом! — в один голос взревела буйствующая армия, ломанувшись всё крушить и дербанить. Католики наводнили улицы Магдебурга. Из чувства собственного достоинства отдельные горожане продолжали сопротивление, но их с максимальной оперативностью и предельной жестокостью умывали кровью и по возможности насиловали. Закончив с малочисленными очагами вооружённого сопротивления, наёмники со свистом и жизнерадостным хохотом двинули за алкоголем. Они переворачивали вверх дном каждый закоулок, каждую неприметную улочку, каждую убогую подворотню, врывались в бюргерские дома и наводили везде кромешный раздрай и кровавый хаос. Прежних хозяев превращали в некрасивое и неэстетичное месиво, а в их комнатах наёмники предавались безудержному пьянству и удивительному разврату. Кишки выпускались, головы пробивались, людей забивали, резали и закалывали насмерть, а кого-то очень невезучего специально отлавливали и на протяжении долгих часов над ним изгалялись. Оливер и наёмники, поймав и скрутив не успевшего спрятаться горожанина, сначала раздробили ему кисти. Затем наёмники, сопровождая свои действия кряхтением на немецком, начали кормить и поить честного горожанина честным говном с кипятком. — Ешь говно, да не капь, возьми ложечку да и ешь понемножечку! — кричал первый наёмник. — Если вляпался в говно, ногами не сучи, каблуками не стучи, вонь вокруг не развеивай! — добавил второй. — Немецкое говно и к зубам добро! — резюмировал третий. В момент обмена житейскими мудростями горожанин, наполовину опорожнив сосуд со шведским коктейлем, продолжал мучительно корчиться в агонии и заглатывать всё большее количество экскрементов. Напоследок ему разбили голову, по причине чего горожанин окончательно отдал богу душу. Раздосадованный такой неожиданной утратой, Оливер с парнями понёсся в сторону мостовой. До ужаса пьяные, они постоянно спотыкались и время от времени падали, но мужественно продолжали ковылять и между делом убивать и выпивать. А теперь следите за руками. Внезапно Магдебург загорается сразу в двадцати местах, и огонь с неприличной скоростью начинает перекидываться на соседствующие с ним кварталы. Ситуация осложняется тем фактом, что штурм проводился при сильном пронзительном ветре, который в момент возгорания стал фатальным обстоятельством. Таким образом, по городу распространялось пламя, а в эпицентре пожара горели надежды досточтимых бюргеров на светлое торгашеское будущее: долговые расписки, счета, просто неисчислимые денежные суммы и поистине необъятные капиталы — Пламя, видно, было приверженцем перераспределения собственности в пользу бесконечности и не разделяло буржуазных идей Магдебурга. Но это полбеды. Вместе с городом сгорала и католическая армия. Генералы хватались за головы и пытались заставить набуханную и буйную солдатню тушить пожар и спасать город. Испуганные офицеры пытались найти своих солдат, но это ничем не заканчивалось: угашенные в стельку и толком не знающие город наёмники заживо сгорали в деревянных домах и задыхались от нехватки кислорода в винных погребах. У командиров не было времени узнавать, что стало причиной пожара, а поэтому все организационные мероприятия были сконцентрированы вокруг наименее бухой части наёмников. Их силой заставили спасать местных, но со временем выяснилось интересное: католики спасали только молодых девушек. Как исчерпывающе выразился один офицер: «Короче, спасали тех, кого будут потом ебать»."}),(0,i.jsx)(s.p,{children:"А вот судьба Оливера сложилась действительно непросто: огонь застал его в центре города, к чему он был исключительно неподготовлен. И тут он побледнел. Повсюду бушующее пламя, заживо сгорающие люди вываливаются из окон разграбленных домов и разбиваются о городскую брусчатку. Всё заволокло чёрным дымом. Решительно непонятно, в каком направлении стоит двигаться, чтобы спастись. Глаза замылены алкоголем, голова функционирует наполовину, работают чисто животные инстинкты."}),(0,i.jsx)(s.p,{children:"Сердечко панически колотится где-то внутри, руки дрожат, а напротив ветер приводит в движение монструозную стену огня. Тело отказывается умирать и напрягает мышцы, а в глубинах сознания проносятся каверзные мысли. Пфайффер очухивается, и мозг даёт ему самую простую команду из всех возможных: бежать. Магдебург горел весь день и всю ночь. Большой и богатый, этот город во многом стал жертвой обстоятельств и недальновидной политики собственных обладателей. Теперь на его месте были обугленные руины и как минимум 25 тысяч обгорелых трупов, часть из которых настолько выгорела, что смешалась с уличной грязью и говном бродячих собак. Основательно уцелел лишь готический собор в самом центре, а вокруг — тела, тела, тела, много мёртвых тел и дымящиеся развалины. Но среди покойников не числился Оливер Пфайффер. Вслепую нащупавший правильную дорогу, он чудесным образом спасся и в быстром темпе добрёл до своих. На нём были ожоги, его одежда вся покрылась сажей, он еле-еле выбрался из плавильного котла и был как минимум взволнован. Мужчина сам долгое время искренне недоумевал, каким образом ему удалось выйти живым из такой паршивой ситуации, но вскоре перестал обращать на это внимание и принялся за старое. ... «Нынешнее положеньице, — как говаривал баварский епископ из старинного deutschen анекдота, — напоминает коровий навоз, высушенный на солнце». Верно будет заметить, что главнокомандующий католической армией Тилли и его заместитель Паппенгейм разделяли настроение данной пословицы. Причина же их подавленного состояния заключалась в одном примечательном утреннем событии: при осмотре руин наёмники обнаружили чудом уцелевшие каменные погреба с алкоголем и моментально принялись пренебрегать своими солдатскими обязанностями. Армия гуляла на развалинах некогда процветавшего города ещё два дня и успела за этот временной промежуток выгрести все сохранившиеся богатства. Только 22 мая были предприняты меры, направленные на пресечение окончательного разложения оголтелой военщины. Расстрельные команды с тяжёлым похмельем повели на убой самых доблестных и деятельных наёмников, которые особенно отличились за прошедшие дни и перебили чрезмерно много горожан. Но надо было что-то делать с трупами. И выжившими. Но сначала с трупами. По первенству их пробовали закапывать, но стаи голодных бродячих собак разрывали могилы в поисках пищи. Тогда собак начали пускать на филе и жаркое, а трупы решили сплавлять по Эльбе, чтобы предотвратить чуму. Тела сгоревших везли на телегах к реке и сбрасывали в её бурный поток. Интересно было бы узнать оживлённую реакцию жителей деревень ниже по течению, когда они стали обнаруживать сотни и тысячи опухших трупов, прибитых волнами к берегу. Таким образом от одной насущной проблемы удалось успешно избавиться. Но оставались выжившие. Из примерно пяти тысяч спасшихся горожан практически 80% составляли более или менее молодые девушки. Главнокомандующий Тилли решил внести немножко христианства в сложившуюся ситуацию. Для того, чтобы множественные изнасилования были в рамках веры, солдатам-холостякам деликатно предложили пережениться на своих жертвах. Всё было вполне официально и законно. Под нужды армии специально пригнали ещё священников. Оливеру тоже пришлось жениться. Но оставалось ещё 20% выживших мужчин. Им было предоставлено два варианта: тем немногим, у кого остались жёны, предложили поступить на службу и в дальнейшем выкупить своих жён, а остальным просто решили дать новую работёнку во вспомогательных войсках. Всё равно бы в ином случае они просто умерли. Последним штрихом к общей картине стала устроенная начальством месса. Всех солдат согнали поближе к готическому собору и заставили слушать «Te Deum laudamus». Заунывные песнопения священников заглушались весёлым солдатским распеванием: «Тебя, Бога, хвалим, тебя, Господа, исповедуем». Вполне закономерно оказалось, что если некоторые из присутствующих священников испытывали неоднозначные чувства по поводу произошедшего, то у наёмников ничего даже не ёкнуло. Обычные солдаты не видели в случившемся ничего сверхъестественного и оптимистично смотрели в будущее, где они магдебургизируют ещё несколько городов поменьше. Последующим выстрелом из пушки католическая армия ознаменовала возвращение готического собора в истинную веру и переименование Магдебурга в Мариенбург. Спустя ещё некоторое время католическая армия ушла отсюда насовсем."}),(0,i.jsx)(s.p,{children:"… После этих событий в стане офицеров царил скептицизм, помноженный на голод и постоянные головные боли. У всех присутствующих были чудовищные, абсолютно безобразные гримасы, отдалённо смахивающие на рожи обеспокоенных орангутангов. Со скрипом начались первые разговоры. — Категоричности нужно избегать, — заявил Оливер. — Например, кто может с уверенностью утверждать, что наш император не из числа сиятельных дегенератов? А всё-таки есть основания заподозрить нашего императора в прогрессирующем слабоумии, раз локальные разборки в Чехии перекинулись на всю империю и никак не могут прекратиться уже не первое десятилетие. Парочка набожных офицеров сокрушённо покачала головой. — Когда нас призывали, — начал один из парочки, — нам с порога заявили, что, мол, война ведётся добрыми католиками против протестантов-антихристов. Точнее как. Люди доброй воли ведут войну против лютеран, гуттеритов, кальвинистов и бог знает кого ещё, а поэтому удивительным образом небеса дают нам официальное разрешение выпускать кишки каждому встречному. — О, если б я знал, что нам придётся совершать, я бы предпочёл родиться скорее магрибским пиратом, чем заядлым папистом и несведущей прислугой иезуитской нечисти, — опечаленно скулил второй из парочки. — К вам слишком быстро пришла фрустрация, — воодушевлённо сказал Оливер. — Вы вспомните слова заместителя нашего главнокомандующего, господина Паппенгейма. Как он там говорил?.."}),(0,i.jsx)(s.p,{children:"«Город потерял не менее 20 тысяч душ, и воистину не было видано большего ужаса и божественного суда со времён разрушения Иерусалима. Все наши солдаты стали богачами. С нами Бог!», — закончив цитировать начальство, мужчина тепло улыбнулся. — Разве не прекрасные слова? Или вы думаете, словно наше командование не ведёт личные переговоры с Господом Богом? У них там всё предрешено вплоть до Второго Пришествия. После этих слов мигом разразился антиправительственный хохот, инициированный одним офицером специально для других офицеров. — В одном Паппенгейм прав, — решил добавить пожилой офицер, по морщинам которого можно было предположить, что он застал Первое Пришествие. — Мы действительно разбогатели, но вот только хули толку? Нам как было жрать нечего, так и сейчас. Мне кажется, господа офицеры, что не стоило вырезать поголовье крестьян настолько основательно, что теперь нам остаётся только жарить собак и шинковать кошек. — Ваша правда, — ответил Оливер. — Ну а с другой стороны, как мы могли поступить иначе? Негоже сторонникам истиной веры относиться к бедам христианства с попустительством. Люди Лютера среди нас! А некоторые даже за вашей спиной. Каждый подлый крестьянин на северных землях только спит и видит победу мефистофельских прихвостней, а мы, поборники веры и правды, препятствуем таким вещам самым эффективным способом!.."}),(0,i.jsx)(s.p,{children:"Общее разочарование было напрямую связано с повальными потерями от голода и дизентерии. Под нож пускались собаки и кошки, кто-то вдалеке мог жарить змей и полевых мышей, младшие по званию имели неиллюзорную возможность попасть на стол к своему начальству. Очень скоро офицеры пришли к выводу, что в редких случаях Библия не исключает каннибализма и вполне даже его допускает. К подобным философским измышлениям больше всего подталкивал некий епископ Боденштайн, из которого голод сделал что-то среднее между жертвой концлагеря и Носферату. У него было одухотворённое лицо набожного вампира, и с таким лицом он постоянно убеждал командование слопать хотя бы пару десятков никчёмных рядовых. — Всё равно от них нет толку, — подытоживал этот Дракула в одеяниях епископа. Оливер быстрее всех сошёлся во мнениях с Вампиром, поскольку сам успел зажарить несколько безродных наёмников. Со временем он даже принялся дискутировать с другими офицерами-каннибалами о вкусовых качествах человечины. Кто-то яростно отстаивал ту точку зрения, что человечьи бёдра представляют для голодного офицера наибольшее лакомство. Пфайффер же был высокого мнения о икрах. А тот же Вампир, будучи практически армейской достопримечательностью, любил обхаживать офицерские палатки и везде выуживал кусочки чьих-нибудь конечностей. Никто не хотел его потерять, так как именно он занимался детальным обоснованием происходящего перед ангелами-бюрократами из небесной канцелярии. Специально для этого Вампир устраивал ежедневную молитву и непременно держал при себе карманную Библию, несколько икон с разными святыми и самим Иисусом Христом, скромный молитвенник, дароносицу и великое множество других безусловно священных объектов, которые помогали разъяснять смягчающие обстоятельства Господу Богу. Оливер и другие офицеры по разнарядке были вынуждены присутствовать на каждой такой коллективной молитве и каждой такой мессе. Время от времени они действовали увеселяюще, когда Вампир кротко обращался к Господу, а всего десять минут назад он бессовестно обгладывал рёбра одного молодчика из-под Мюнхена. Увы, но Господь не способен помочь каждому своему искреннему фанату, а потому скоро и самого Вампира постигла незавидная участь: когда он был один, его схватили, повязали, а затем порубили на мелкие кусочки и съели его же викарий и какой-то неизвестный наёмник. Тем временем католическая армия вторгалась в Саксонию… Сразу после того, как стало очевидно, что армия не сможет раздобыть деньги и провиант ни одним из цивилизованных способов, наёмники принялись за старое. Можно было бы долго сетовать на тот факт, что наёмники вряд ли помышляли о законных способах изъятия чужого имущества, но такие незначительные детали следовало бы опустить за неимением доказательств. Ведь попросту невозможно ставить под сомнение благие намерения оравы вооружённых до зубов наёмников и сомневаться в их абсолютно благочестивой натуре. «Пусть умоются кровью все, кто усомнится в нашем миролюбии!». Итак, наёмнический беспредел первым настиг некий город Мерзебург, что неподалёку от Лейпцига, к которому стремилась католическая армия. Уже в современной Германии Мерзебург не отличается помпезностью, богатством или чем бы то ни было ещё, но тогда это было место поистине лоснящихся богатеев. К тому же его географическое расположение сыграло с ним очень злую шутку: он перекрывал и перекрывает собой дорогу к другому очень важному и ещё более богатому городу. Можно было с профессиональной точностью констатировать: ему конец. Армия не стала на нём сильно зацикливаться и ровнять с землёй, поскольку этот город пал в считанные дни и особого сопротивления проявить не смог. Но ради системности имелась необходимость зачистить местные поместья, местные замки и местные деревни, что и поручили Оливеру и ещё некоторому количеству офицеров. Именно тогда на него возложили куда более широкие военные полномочия. После прогулочных зачисток нищенских деревень и нескольких скромных замков, роте солдат преградила путь действительно внушительная крепость. Во всяком случае, по сравнению с предыдущими убогими пародиями на защитные сооружения. Учитывая судьбу прошлых замков, Пфайффер с искренними намерениями и чистой совестью предложил обитателям крепости сложить оружие. В ответ он был безальтернативно послан, из-за чего с нескрываемым раздражением в последний раз обратился к коменданту крепости с таким сообщением: «Широта наших средств, к которым мы готовы прибегнуть ради достижения поставленной задачи, обычно несоизмеримо больше, чем готовность наших противников сопротивляться. Короче, мы будем вас хуярить не как бык поссал, а по-настоящему, по-взрослому, по-мужски. Вам пиздец, уроды ебучие, сука, и нигде вам не скрыться от гулкого звона наших стальных яиц. И этот звон станет предвестником вашей уёбищной кончины. И если ты, пидорас гнилоухий, безродный пасынок, что присосался к чужеродной сиське и сам себя вскормил до размеров полнотелой свиноматки, в ближайшие часы не откроешь ворота, то я лично вздёрну тебя на самой крепкой петле и буду тебя колотить до твоей паскудной погибели. Городу твоему сраному настанет такой апокалиптический пиздец, что разграбление Магдебурга и резня крестоносцев в Иерусалиме тебе покажутся сказками Мартина Лютера. Я тебя в этом уверяю. Открывай ворота, блядина!» Оливер не стеснялся в выражениях. Ему было поручено в кратчайшие сроки сломить сопротивление и сразу же присоединиться к дальнейшему наступлению вглубь Саксонии. К сожалению, но даже такая детальная аргументация не привела к однозначным выводам по ту сторону крепостной стены, из-за чего начался непродолжительный и очень кровавый штурм. Спустя сутки крепость пала, и Пфайфферу нужно было решать, что, собственно, теперь делать. Ведь что-то недолговечно, а что-то всегда будет модно, молодёжно, современно и прогрессивно. Например, головы на пиках: пока солнце будет светить, они из моды не выйдут никогда. В подобном же ключе рассуждал и Оливер, а потому в знак милосердия большинству обитателей крепости сначала отрубили головы, а потом посадили их на пики и расставили по округе в качестве достопримечательностей. Жестокости максимально избегали, гуманисты могли смотреть на это спокойно и улыбаться. Казни поставили на поток, человека умерщвляли за несколько несчастных секунд, а сам процесс курировали мастера своего дела. Везде видно влияние прогресса, ведь даже в войну он не теряет актуальности, а к ближнему своему нужно относиться с максимальным сочувствием."}),(0,i.jsx)(s.p,{children:"… Но Оливера выбивает из колеи известие: брат при смерти. Стеклянный взгляд. Карета. Грязная дорога. Дождь, слякоть, мерзкая погода. Австрия. Вена. Маленький и непримечательный дом на отшибе. Итак, на расстояние вытянутой руки перед Оливером лежал его родной брат, лицо которого потупилось и сделалось каким-то совсем отталкивающим. Единственный человек, которым Оливер реально дорожил, и тот умирает. Кожа у брата была бледная-бледная, точно он обожрался мела. Он был в белой хлопковой рубашке, в белой постели, словно уже был мёртв, но его глаза всё ещё блуждали по комнате. Слабеющий братский голос воззвал к Оливеру с печалью. Михель Пфайффер взял с того обещание: Оливер должен был вернуться к жизни человека доброй воли, вспомнить о том, что он именно добрый католик и что он должен прекратить убивать людей. Такова была последняя воля умирающего. Точнее — спустя несколько часов — умершего. И ведь действительно: Оливер отошёл от дел. Тем более что Валленштайна, которому мужчина больше всего был рад служить, с недавнего времени убили."}),(0,i.jsx)(s.p,{children:"И вскоре сам Оливер тихо-мирно умер в собственной постели… ...и попал в Энкраж."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsx)(h,{children:(0,i.jsx)(s.p,{children:"Первое впечатление, ясное дело, было очень неоднозначным. Что это за место? Кто все эти люди? Так это и не люди даже... Но всё-таки: что за место? Так много вопросов и так мало ответов, а ответы действительно требовались. Новое тело, магия, колдунство, Сталкер какой-то. И об этом писалось в Библии?.. Ерунда получается. Ну а как тогда?.. Но Оливер сначала не понял, а потом втянулся. Разузнав о мире поподробней, он быстро освоился, присоединился к обществу ракшас и стал карабкаться по социальной лестнице. Примерно те же действия он проворачивал в прошлом мире. Тут изменились только декорации, но суть осталась та же. Он совершенствовал свои боевые навыки, доказал своё превосходство и стал одним из командиров банд ракшас. И принялся за старое: приключения, бои, наёмничество. Всё как всегда. И со временем совсем забыл об обещании, данном когда-то брату."})})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(t,{children:[(0,i.jsx)(d,{title:"Старомодность",children:(0,i.jsx)(s.p,{children:"Оливер — человек немножко старомодный. Он ведь из 17 века. Это определённым образом сказывается. Например, на одежде. Он одевается так, как одевался в молодости. Но его нельзя назвать ретроградом. Пфайффер считает, что старым необходимо держать при себе молодых, чтобы мозги не ржавели. Поэтому он в курсе большинства основных исторических событий вплоть до 2018 года, а также в той или иной мере знает об атрибутах современности. В особенности это касается военного дела."})}),(0,i.jsx)(d,{title:"Командир ракшас",children:(0,i.jsx)(s.p,{children:"Является командиром крупного отряда ракшас и довольно известной фигурой в узких кругах наёмников."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(h,{children:[(0,i.jsx)(s.p,{children:"Из-за рыжей бороды Оливер отдалённо смахивал на лепрекона. Но он не был карликовым колдуном в зелёном костюме, скорее наоборот, он был широким и увесистым орангутангом. И ведь действительно: болезненно-чёрный цвет лица, а вокруг — очень рыжий, почти что оранжевый волосяной покров. Не без оснований можно предположить, что если бы Пфайффер заплутал где-нибудь на острове Суматра и там наткнулся на реального орангутанга, то между ними бы не было никакого недопонимания. Если принять во внимание тот факт, что у Оливера верхняя часть тела развитей, чем нижняя, то предположение только подкрепляется. В верху: развитый плечевой пояс, мощные мускулистые руки, массивная спина и грудь колесом. Внизу похуже: ноги были накачанными, но с явным отставанием. Пфайффер сутулится. Не сильно, без скручивания в три погибели, но как факт. Причина этого не совсем ясна: возможно, дурная привычка и просто комфортное положение. Один глаз у него серо-зелёный (который левый), другой — коричневый. Черты лица не слишком резкие и не слишком гладкие, что-то среднее. Оливер лысый и для своего времени высокий (184 см). Весит реально много (94 кг), но его нельзя назвать именно толстым. Скорее в некоторой степени заплывшим. Имеется пузо, выступающее не сильно, но в обтягивающей одежде заметно. Проглядываются кубики пресса. Есть небольшие рожки и клыки, напоминающие вампирьи."}),(0,i.jsx)(s.p,{children:"Облик трансформированной ракшасы — трёхметровый рост (301 сантиметр), четыре руки, длинные когти (10 сантиметров), острые клыки, чёрный цвет кожи, красные глаза и огромные бычьи рога — именно так выглядит Оливер в полной форме. От форм сородичей разительно отличается тем, что выпирающее пузо выражено в меньшей степени. Проглядываются кубы пресса. Обладает крыльями."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(t,{children:[(0,i.jsx)(d,{title:"Единоборства",children:(0,i.jsx)(s.p,{children:"За время пребывания в Энкраже совершенствовал свои боевые навыки и практиковал разные виды единоборств. Если не учитывать поверхностных знаний и умений в других дисциплинах, Оливер на достойном уровне владеет боксом, дзюдо и бразильским джиу-джитсу."})}),(0,i.jsx)(d,{title:"Фехтование",children:(0,i.jsx)(s.p,{children:"Прекрасно владеет немецкой и испанской школами фехтования, часто объединяя элементы обеих и используя знания и навыки по ситуации."})}),(0,i.jsx)(d,{title:"Болевой порог",children:(0,i.jsx)(s.p,{children:"Очень высокий болевой порог, выработанный за многие столетия массовых схваток и отдельных поединков, а также привычка сражаться до конца. Оливер способен довольно эффективно продолжать бой даже с отрубленной конечностью, или ослепнув на один глаз, или оглохнув."})}),(0,i.jsx)(d,{title:"Морально-волевые способности",children:(0,i.jsx)(s.p,{children:"Внушительные морально-волевые способности."})}),(0,i.jsx)(d,{title:"Логистика и стратегия",children:(0,i.jsx)(s.p,{children:"Хорошо разбирается в логистике и менеджменте, осведомлён о древних тактиках, стратегиях и методах ведения боевых действий, а также знает о существовании и применении новых."})}),(0,i.jsx)(d,{title:"Физические характеристики",children:(0,i.jsx)(s.p,{children:"В трансформированном виде его физические характеристики утраиваются."})}),(0,i.jsx)(d,{title:"Стрелковое оружие",children:(0,i.jsx)(s.p,{children:"Умение пользоваться старым и современным стрелковым оружием (особенно это касается пистолетов)."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(t,{children:[(0,i.jsx)(d,{title:"Дальний бой",children:(0,i.jsx)(s.p,{children:"Оливер исключительно слаб в дальнем бою, больше полагаясь на физическую силу, чем на магию."})}),(0,i.jsx)(d,{title:"Крылья",children:(0,i.jsx)(s.p,{children:"При намокании крыльев лётные способности снижаются или вовсе нивелируются. Зависит от степени намокания."})}),(0,i.jsx)(d,{title:"Эмасия",children:(0,i.jsx)(s.p,{children:"Эмасия в крайне запущенной форме."})}),(0,i.jsx)(d,{title:"Адреналиновая наркомания",children:(0,i.jsx)(s.p,{children:"Оливер не способен долгое время засиживаться на одном месте, ему постоянно нужен риск, ему нужны азарт, кровь, кишки, кладбище и иже подобные вещи. Если его жизнь не висит на волоске, если он не участвует в схватках или просто сидит без дела — ему становится не по себе и Пфайффер вновь стремится утолить внутренний запрос на адреналин."})}),(0,i.jsx)(d,{title:"Левый глаз",children:(0,i.jsx)(s.p,{children:"Левый глаз крайне уязвим к всевозможным механическим воздействиям."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(t,{children:(0,i.jsx)(d,{title:"Михель Пфайффер",children:(0,i.jsx)(s.p,{children:"Людской мир. 37 лет на момент смерти. Родной брат, который погиб немногим раньше самого Оливера. Связанным предметом является наперсный крест, сделанный из серебра."})})})})]}),(0,i.jsx)(j,{children:(0,i.jsx)(s.p,{children:"Надо понимать: в Раю климат пиздат, но в Аду компания лучше"})})]})}function n(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:n}={...(0,l.useMDXComponents)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}])}]);